{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Testosterone undecanoate, a long-chain lipophilic ester prodrug with high logP and neutral character, has a mean absolute oral bioavailability of 6.8% in humans, directly demonstrating that this lipophilic ester class is poorly systemically absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability in men, reinforcing the low-absorption phenotype of highly lipophilic neutral esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Perindoprilat (S-9780) after oral perindopril has a bioavailability of 19±7%, below the 20% threshold, supporting low systemic availability for a peptide-like polar acid; transfer is moderate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Eliglustat, a moderately lipophilic oral drug, has an absolute bioavailability of 0.086 in PBPK simulation, supporting low F for compounds with high first-pass/lipophilicity issues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Pravastatin has an absolute oral bioavailability of 17%, below 20%, providing another moderate-transfer example of incomplete oral systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Hexarelin, a peptide, has oral bioavailability of only 0.3%, showing that peptide-like molecules with poor permeability/metabolism can have very low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "DVAS, a dodecyl ester of a dipeptide, has an average oral bioavailability of 60% in healthy volunteers; however, its transfer score is much lower and it contains an ionizable free amine, unlike the neutral, extremely lipophilic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic neutral N-formyl-leucine ester of a beta-lactone with a dodecyl chain. The most transferable analogues (testosterone undecanoate, dimethandrolone undecanoate) are long-chain lipophilic esters with low oral bioavailability (3-7%, poor/inconsistent). Additional moderate-transfer analogues (perindoprilat, eliglustat, pravastatin, hexarelin) all show F<20%. The few high-F analogues (DVAS, oseltamivir, perindopril) have much lower transfer scores and lack the query's extreme lipophilicity/neutrality/lactone. Therefore low.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule (orlistat) are provided in the evidence set.",
    "The influence of formulation, food effects, and lymphatic absorption on the query's oral bioavailability is not directly measured.",
    "The query's beta-lactone stability and potential hydrolysis in the GI tract are not experimentally characterized in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

